#include <cstdint>
#include <cstring>

uintptr_t FindPattern(const uint8_t* base, size_t size, const char* pattern, const char* mask) {
    const size_t patLen = std::strlen(mask);
    if (size < patLen) return 0;
    for (size_t i = 0; i <= size - patLen; ++i) {
        bool matched = true;
        for (size_t j = 0; j < patLen; ++j) {
            if (mask[j] == 'x' && base[i + j] != static_cast<uint8_t>(pattern[j])) {
                matched = false;
                break;
            }
        }
        if (matched) return reinterpret_cast<uintptr_t>(base + i);
    }
    return 0;
}
```

