#include <windows.h>
#include <cstdint>

template <typename T>
bool ReadMem(HANDLE hProcess, uintptr_t address, T& outValue) {
    SIZE_T bytesRead = 0;
    return ReadProcessMemory(
        hProcess,
        reinterpret_cast<LPCVOID>(address),
        &outValue,
        sizeof(T),
        &bytesRead
