#include <windows.h>

void* HookVMT(void** vtable, size_t index, void* detourFn) {
    DWORD oldProtect = 0;
    if (!VirtualProtect(&vtable[index], sizeof(void*), PAGE_EXECUTE_READWRITE, &oldProtect)) {
        return nullptr;
    }
    void* originalFn = vtable[index];
    vtable[index] = detourFn;
    VirtualProtect(&vtable[index], sizeof(void*), oldProtect, &oldProtect);
    return originalFn;
}
