```python
CIPHER_MAP = {
    "q1": "а", "w2": "б", "e3": "в", "r4": "г", "t5": "д", "y6": "е",
    "h(": "п", "j)": "р", "o9": "и", "l+": "т", "a$": "к", "s%": "л",
    "*i": "h", "%t": "e", "+s": "l", "[g": "o", "!q": "a", "c/": "w"
}

def decode_cipher(text: str) -> str:
    out, i = [], 0
    while i < len(text):
        pair = text[i:i+2].lower()
        if pair in CIPHER_MAP:
            out.append(CIPHER_MAP[pair])
            i += 2
        else:
            out.append(" " if text[i] == "_" else text[i])
            i += 1
    return "".join(out)
```

