```python
import numpy as np

class ScratchNet:
    def __init__(self, in_dim=256, hidden_dim=2048, out_dim=59):
        self.W1 = np.random.randn(in_dim, hidden_dim).astype(np.float32) * 0.04
        self.W2 = np.random.randn(hidden_dim, out_dim).astype(np.float32) * 0.04

    def forward(self, x):
        self.h = np.tanh(x @ self.W1)
        logits = self.h @ self.W2
        exp = np.exp(logits - logits.max(axis=-1, keepdims=True))
        return exp / exp.sum(axis=-1, keepdims=True)
